import sys
sys.path.insert(0, 'src')
from workflow import Session

class Env:
    def __init__(self):
        self.listeners=[]; self.deferred=[]; self.calls=[]; self.warm=[]
    def bind(self, f): return f
    def call(self, name, *args):
        self.calls.append((name, args))
        if name == 'listen':
            self.listeners.append(args[1]); return args[1]
        if name == 'unlisten':
            if args[1] in self.listeners: self.listeners.remove(args[1])
        elif name == 'start':
            for packet in list(self.warm):
                for listener in list(self.listeners): listener(packet)
        elif name == 'decode':
            packet=args[1]; done=args[2]
            if packet.startswith('defer:'):
                self.deferred.append((packet[6:], done)); return {'deferred': True}
            return {'deferred': False, 'frame': packet}

def frames(env): return [args[0]['frame'] for name,args in env.calls if name == 'showProgress']
def audits(env): return [args[0]['frame'] for name,args in env.calls if name == 'recordProgress']
file={'id':'f','token':'t','feed':True}
# Warm frame is delivered during start, after the listener and attempt handle exist.
env=Env(); env.warm=['warm']; session=Session(env); session.select(file)
assert frames(env) == ['warm'], frames(env)
# Later decode completion of an older packet cannot replace a newer displayed frame.
env=Env(); session=Session(env); h=session.select(file)
for listener in list(env.listeners): listener('defer:old'); listener('new')
assert frames(env) == ['new'], frames(env)
old, done=env.deferred.pop(); done(old)
assert frames(env) == ['new'], frames(env)
assert audits(env) == ['new', 'old'], audits(env)
# A warm progress callback may navigate; the bound handle is cancelled immediately.
env=Env(); session=Session(env)
def navigate(frame):
    if frame == 'warm': session.hide()
old_show=env.call
def call(name,*args):
    result=old_show(name,*args)
    if name == 'showProgress': navigate(args[0]['frame'])
    return result
env.call=call; env.warm=['warm']; session.select(file)
assert session.snapshot()['visitId'] is None
assert not env.listeners
print('focused lifecycle checks passed')
