import sys
sys.path.insert(0, 'src')
from workflow import Session, Telemetry

class Env:
    def __init__(self): self.listeners=[]; self.deferred=[]; self.calls=[]; self.warm=[]
    def bind(self, fn): return fn
    def call(self, name, *args):
        self.calls.append((name,args))
        if name == 'listen': self.listeners.append(args[1]); return args[1]
        if name == 'unlisten':
            if args[1] in self.listeners: self.listeners.remove(args[1])
        if name == 'start':
            for packet in list(self.warm):
                for listener in list(self.listeners): listener(packet)
        if name == 'decode':
            packet, done = args[1:]
            if packet[0] == '!': self.deferred.append((packet[1:],done)); return {'deferred':True}
            return {'deferred':False,'frame':packet}

def values(env, method): return [args[0]['frame'] if isinstance(args[0],dict) else args[0] for name,args in env.calls if name == method]
file={'id':'f','token':'t','feed':True}
env=Env(); env.warm=['initial']; Session(env).select(file)
assert values(env,'showProgress') == ['initial']
env=Env(); s=Session(env); s.select(file); env.listeners[-1]('!old'); env.listeners[-1]('new'); env.deferred.pop()[1]('old')
assert values(env,'showProgress') == ['new']
assert values(env,'recordProgress') == ['new','old']
# Telemetry retains its existing start/listen order and later streaming behavior.
env=Env(); t=Telemetry(env,file); env.listeners[-1]('delta'); assert values(env,'recordDelta') == ['delta']; t.stop()
print('warm, ordering, audit, and telemetry checks passed')
